    status = try container.decode(CoreCount.self, forKey: .status)
    try CoreContract.checkInteger(status)
    data = try container.decode(CoreJSONValue.self, forKey: .data)
    retryAfterSeconds = container.contains(.retryAfterSeconds) ? try container.decode(CoreCount.self, forKey: .retryAfterSeconds) : nil
    if let value = retryAfterSeconds { try CoreContract.checkInteger(value) }
  }
  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try CoreContract.checkInteger(status)
