public protocol CoreRequest: Sendable {
  associatedtype Arguments: Encodable & Sendable
  associatedtype Response: Decodable & Sendable
  static var method: String { get }
  var arguments: Arguments { get }
}

public enum CoreRequests {
  public struct Catalog: CoreRequest {
    public typealias Arguments = CoreEmptyArgs
    public typealias Response = CoreCatalog
    public static let method = "catalog"
    public var arguments: Arguments
    public init(_ arguments: Arguments) { self.arguments = arguments }
  }
  /// columns is SQL projection and may omit id, updated_at and hidden fields; fetch a full row before editing. For visible layout only, omit columns when querying rows.
  public struct Rows: CoreRequest {
    public typealias Arguments = CoreView
    public typealias Response = [CoreWorkspaceRow]
    public static let method = "rows"
    public var arguments: Arguments
    public init(_ arguments: Arguments) { self.arguments = arguments }
