    public typealias Response = CoreEnrollmentApproval
    public static let method = "enrollmentApproval"
    public var arguments: Arguments
    public init(_ arguments: Arguments) { self.arguments = arguments }
  }
  /// Pure nonadmin identity validation and current full-scope replica eligibility. Dedicated manual names are allowed. No network or storage.
  public struct ValidateDeviceSession: CoreRequest {
    public typealias Arguments = CoreSessionDataArgs
    public typealias Response = CoreSessionInfo
    public static let method = "validateDeviceSession"
    public var arguments: Arguments
